/*
 * Optional Linux x86-64 hardware observation fixture. Requires GCC-compatible
 * inline assembly and MAP_32BIT. It prints observations, not an acceptance flag.
 * Build and run from the repository root (all products stay ignored):
 *
 *   mkdir -p target/rep-address-hardware
 *   cc -O0 tests/bap/fixtures/repeated-string/address32-hardware/probe.c -o target/rep-address-hardware/probe
 *   LC_ALL=C lscpu > target/rep-address-hardware/cpu.txt
 *   timeout 30 target/rep-address-hardware/probe > target/rep-address-hardware/observations.jsonl
 *
 * Scope: 28 exact canonical address-size-32 memory REP encodings, low counts
 * 0/1/3 with nonzero upper RCX, both DF values, and nonzero upper RSI/RDI.
 * There are 168 observations. Memory is allocated below 2 GiB; only its low
 * 32-bit address is usable. Each instruction restores DF before returning to C.
 * Initial ZF is not controlled, so printed flags are observations only.
 *
 * Corroboration: at low count zero the selected AMD semantics preserve all
 * supplied upper lanes. With nonzero count, let completed = initial low count
 * minus final RCX: used indices become (initial low index +/- element bytes *
 * completed) modulo 2^32, while unused indices retain their full initial value.
 * Local Ryzen 7950X observations matched these clauses. Intel Core 5 220H
 * observations differ at zero count; retain the measured CPU identity and
 * never promote one host's observations into a universal x86 contract.
 *
 * This probe is optional corroboration, not a portable-unit-test prerequisite
 * or coverage of exceptions, partial faults, restart, I/O, or all CPU models.
 * The executable body is preserved from the original qualification probe.
 */
#define _GNU_SOURCE
#include <stdint.h>
#include <stdio.h>
#include <sys/mman.h>
#include <unistd.h>
